root='/root/papers/all'

# Keywords ordered by category priority
keywords = OrderedDict([
    ('LLM', [
        'large language model','language model','llm','transformer','attention','self-attention','gpt','bert','t5',
        'prompt','prompting','in-context','few-shot','zero-shot','chain-of-thought','instruction','rlhf',
        'pretraining','fine-tuning','finetuning','token','tokenization','embedding','retrieval-augmented','rag',
        'chatgpt','llama','mistral','generative language','nlp','natural language','decoder-only'
    ]),
    ('trapped_ion_and_qc', [
        'trapped ion','ion trap','paul trap','penning trap','mølmer','molmer','sorensen','mølmer–sørensen',
        'quantum computing','quantum computer','quantum processor','quantum gate','qubit','qbit','quantum bit',
        'quantum error','error correction','quantum information','entanglement','superposition','quantum algorithm',
        'shor','grover','ion chain','laser cooling','phonon','rydberg'
    ]),
    ('black_hole', [
        'black hole','event horizon','hawking','schwarzschild','kerr','singularity','accretion','accretion disk',
        'gravitational wave','gravitational waves','general relativity','relativistic','supermassive','agn','quasar',
        'eht','event horizon telescope','spacetime'
    ]),
    ('DNA', [
        'dna','deoxyribonucleic','genome','genomic','gene','genes','genetic','chromosome','nucleotide','base pair',
        'sequencing','polymerase chain reaction','pcr','crispr','genotype','allele','rna','mrna'
    ]),
    ('music_history', [
        'music history','musicology','composer','composition','symphony','sonata','concerto','opera','orchestra',
        'baroque','renaissance','classical period','romantic','mozart','beethoven','bach','haydn','chopin',
        'jazz','blues','rock','hip hop','folk','gospel','motet','choral','counterpoint'
    ]),
])

# Compile regex patterns
patterns = {cat: [] for cat in keywords}
for cat, words in keywords.items():
    for w in words:
        if re.search(r'\s', w):
            patterns[cat].append(re.compile(re.escape(w)))
        else:
            patterns[cat].append(re.compile(r'\b'+re.escape(w)+r'\b'))


def extract_pdf(path, max_pages=6):
    import pdfplumber
    text = []
    try:
        with pdfplumber.open(path) as pdf:
            for page in pdf.pages[:max_pages]:
                t = page.extract_text() or ''
                if t:
                    text.append(t)
    except Exception:
        return ''
    return '\n'.join(text)


def extract_docx(path):
    try:
        with zipfile.ZipFile(path) as z:
            xml = z.read('word/document.xml').decode('utf-8', errors='ignore')
    except Exception:
        return ''
    texts = re.findall(r'<w:t[^>]*>(.*?)</w:t>', xml)
    return html.unescape(' '.join(texts))


def extract_pptx(path):
    try:
        with zipfile.ZipFile(path) as z:
            slide_names = [n for n in z.namelist() if n.startswith('ppt/slides/slide') and n.endswith('.xml')]
            slide_names.sort()
            chunks = []
            for name in slide_names[:10]:
                xml = z.read(name).decode('utf-8', errors='ignore')
                texts = re.findall(r'<a:t[^>]*>(.*?)</a:t>', xml)
                if texts:
                    chunks.append(' '.join(texts))
            return html.unescape(' '.join(chunks))
    except Exception:
        return ''


def score_text(text):
    tl = text.lower()
    scores = {cat: 0 for cat in keywords}
    for cat, regs in patterns.items():
        s = 0
        for r in regs:
            s += len(r.findall(tl))
        scores[cat] = s
    return scores


files = [f for f in os.listdir(root) if not f.startswith('.')]
results = {}

for fname in files:
    path = os.path.join(root, fname)
    ext = os.path.splitext(fname)[1].lower()
    if ext == '.pdf':
        text = extract_pdf(path)
    elif ext == '.docx':
        text = extract_docx(path)
    elif ext == '.pptx':
        text = extract_pptx(path)
    else:
        text = ''
    # include filename as weak signal
    text = (fname + '\n' + text)
    scores = score_text(text)
    # pick max score with priority order
    best_cat = None
    best_score = -1
    for cat in keywords.keys():
        sc = scores[cat]
        if sc > best_score:
            best_score = sc
            best_cat = cat
    if best_score <= 0:
        best_cat = 'music_history'
    results[fname] = (best_cat, best_score)

# summary
from collections import Counter
cnt = Counter(cat for cat,_ in results.values())
print('category counts:', cnt)
# print low-confidence items
low = [ (f,cat,sc) for f,(cat,sc) in results.items() if sc <= 1 ]
print('low-confidence:', len(low))
print('\n'.join([f"{f}\t{cat}\t{sc}" for f,cat,sc in sorted(low)][:20]))

# write mapping file for inspection
with open('/root/papers/classification_preview.tsv','w') as out:
    for f,(cat,sc) in sorted(results.items()):
        out.write(f"{f}\t{cat}\t{sc}\n")

